 async function handleReceiptImage(file?:File){if(!file)return;if(!file.type.startsWith('image/')){setError('Selecciona una imagen válida (JPG, PNG o WebP).');return;}if(file.size>4*1024*1024){setError('La imagen debe pesar menos de 4 MB.');return;}setReceiptScanning(true);setError('');try{const reader=new FileReader();const base64Promise=new Promise<string>((resolve,reject)=>{reader.onload=()=>{const res=reader.result as string;const comma=res.indexOf(',');resolve(comma>=0?res.slice(comma+1):res);};reader.onerror=reject;});reader.readAsDataURL(file);const base64=await base64Promise;const r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:{mimeType:file.type,base64},text:'Extrae los datos de esta factura, recibo o comprobante para registrar en COP.'})});const d=await r.json() as {error?:string;reply?:string;movement?:Omit<Movement,'id'|'source'>|null};if(!r.ok)throw Error(d.error||'No pudimos procesar la imagen.');if(!d.movement)throw Error(d.reply||'No detectamos un importe o gasto claro en la imagen.');setDraft({...blank(),...d.movement,id:crypto.randomUUID(),source:'Foto recibo'});setEdit(false);setModal('movement');setNotice('Comprobante analizado por Gemini. Revisa antes de confirmar.');}catch(e){setError((e as Error).message);}finally{setReceiptScanning(false);}}
