 function budgetList(full=false){return <div className="budget-list">{budgetRows.filter(r=>full||r.limit>0||r.actual>0).slice(0,full?9:4).map(r=><div className="budget-row" key={r.category}><div className="row-between"><span className="category-label"><i style={{background:r.color}}/>{r.category}</span><span className={r.actual>r.limit?'negative':''}>{r.percent}%</span></div><Progress value={r.limit?r.actual/r.limit*100:r.actual?100:0} color={r.actual>r.limit?'#c86156':r.color}/><div className="row-between muted small"><span>{money(r.actual)}</span><span>de {money(r.limit)}</span></div>{full&&r.actual>r.limit&&<p className="negative small">Superaste el plan por {money(r.actual-r.limit)}.</p>}</div>)}</div>;}
