 {view==='Resumen'&&<><section className="stats-grid"><article className="balance-card"><div className="row-between"><span>Disponible del mes</span><Wallet size={21}/></div><div className="balance-number">{money(totals.available)}</div><span className="balance-caption">Ingresos − gastos − aportes a metas</span><div className="balance-footer"><span>Tu mes, bajo control</span><span>COP</span></div></article><article className="stat-card"><span className="stat-icon green"><ArrowDownLeft size={20}/></span><span className="muted">Ingresos del mes</span><strong>{money(totals.income)}</strong><span className="stat-caption">{monthly.filter(r=>r.kind==='income').length} entradas registradas</span></article><article className="stat-card"><span className="stat-icon peach"><ArrowUpRight size={20}/></span><span className="muted">Gastos del mes</span><strong>{money(totals.expense)}</strong><span className="stat-caption">{totals.income?Math.round(totals.expense/totals.income*100):0}% de tus ingresos</span></article><article className="stat-card"><span className="stat-icon purple"><Sprout size={20}/></span><span className="muted">Aportes a metas</span><strong>{money(totals.saving)}</strong><span className="stat-caption">{savingsRate}% de tus ingresos <span className="mini-tag">Meta 20%</span></span></article></section>
 <div className="dashboard-columns"><div className="left-column"><section className="card chart-card"><div className="section-heading"><div><h2>Así se mueve tu dinero</h2><p>Ingresos y gastos acumulados</p></div><div className="chart-legend"><span><i style={{background:'#388b77'}}/>Ingresos</span><span><i style={{background:'#b7c9c2'}}/>Gastos</span></div></div><div className="trend-chart" role="img" aria-label={'Gráfica acumulada: ingresos '+money(totals.income)+', gastos '+money(totals.expense)}><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend} margin={{top:10,right:8,left:-15,bottom:0}}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#398e77" stopOpacity={.14}/><stop offset="100%" stopColor="#398e77" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf0ef" strokeDasharray="4 5"/><XAxis dataKey="day" tickLine={false} axisLine={false} ticks={[1,5,10,15,20,25,days]} tick={{fill:'#8a9691',fontSize:12}} tickFormatter={v=>String(v).padStart(2,'0')}/><YAxis tickLine={false} axisLine={false} tick={{fill:'#8a9691',fontSize:12}} tickFormatter={v=>v>=1e6?`${v/1e6} M`:v>=1000?`${v/1000} mil`:v}/><Tooltip formatter={(v)=>money(Number(v))} labelFormatter={v=>`Día ${v}`} contentStyle={{borderRadius:14,borderColor:'#e7ece9'}}/><Area type="stepAfter" dataKey="Ingresos" stroke="#398e77" strokeWidth={2.5} fill="url(#incomeFill)"/><Area type="stepAfter" dataKey="Gastos" stroke="#a9bfb5" strokeWidth={2} fill="transparent"/></AreaChart></ResponsiveContainer></div></section>
 <section className="card"><div className="section-heading"><h2>Últimos movimientos</h2><button className="text-button" onClick={()=>setView('Movimientos')}>Ver todos<ArrowUpRight size={15}/></button></div><p className="small muted">Las filas violetas son compras a crédito; sus pagos se muestran por separado.</p>{movementList(5)}</section>
 <section className="coach-strip"><span className="coach-icon"><Sparkles size={23}/></span><div><h3>{totals.income===0?'Tu primer paso: conocer tus ingresos':savingsRate>=20?'Tu constancia está dando frutos':'Hazle espacio a tu tranquilidad'}</h3><p>{totals.income===0?'Registra tus ingresos netos y adapta tu presupuesto a tu realidad.':savingsRate>=20?'Has destinado al menos el 20% de tus ingresos a tus metas este mes.':`Para destinar el 20% a tus metas, te faltarían ${money(Math.max(0,totals.income*.2-totals.saving))}. Ajusta el objetivo a tus gastos esenciales.`}</p></div><button aria-label="Ver consejos financieros" onClick={()=>open('help')}><ArrowUpRight size={22}/></button></section></div>
 <div className="right-column"><section className="card spending-card"><div className="section-heading"><h2>¿En qué gastas?</h2><span className="small muted">Este mes</span></div><div className="donut-wrapper" role="img" aria-label={distribution.map(d=>d.name+': '+money(d.value)).join('; ')||'Sin gastos'}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={distribution.length?distribution:[{name:'Sin gastos',value:1,color:'#e9efec'}]} dataKey="value" innerRadius={69} outerRadius={89} startAngle={90} endAngle={-270} paddingAngle={distribution.length?3:0} cornerRadius={4} stroke="none">{(distribution.length?distribution:[{color:'#e9efec'}]).map((d,i)=><Cell key={i} fill={d.color}/>)}</Pie><Tooltip formatter={v=>money(Number(v))}/></PieChart></ResponsiveContainer><div className="donut-center"><small>Gasto total</small><strong>{money(totals.expense)}</strong></div></div><div className="distribution-legend">{distribution.map(d=><div key={d.name}><span><i style={{background:d.color}}/>{d.name}</span><strong>{Math.round(d.value/totals.expense*100)}%</strong></div>)}{!distribution.length&&<p className="muted">Tus categorías aparecerán aquí.</p>}</div></section>
 <section className="card"><div className="section-heading"><h2>Tu presupuesto</h2><button className="icon-button" aria-label="Editar presupuesto" onClick={()=>{setPlan(structuredClone(p));open('budget');}}><SlidersHorizontal size={18}/></button></div>{budgetList()}<button className="wide-link" onClick={()=>setView('Presupuesto')}>Ver mi plan completo<ChevronRight size={16}/></button></section></div></div></>}
 {view==='Movimientos'&&<section className="card"><p className="credit-ledger-note">💜 Compras a crédito del mes: <strong>{money(monthlyCredit.reduce((a,r)=>a+r.amount,0))}</strong>. Se muestran como deuda; los totales de efectivo cuentan los pagos, para no sumar compra y cuota dos veces.</p>{!creditCatalog.ready&&<p role="status">No se han cargado las compras a crédito. Revisa Tarjetas si no aparecen.</p>}<div className="toolbar"><label className="search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar concepto, categoría o cuenta" aria-label="Buscar movimientos"/></label><select aria-label="Filtrar tipo de movimiento" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todos los movimientos</option><option value="income">Ingresos</option><option value="expense">Gastos y compras a crédito</option><option value="credit">Solo compras a crédito</option><option value="saving">Aportes a metas</option></select><button className="secondary" onClick={()=>open('import')}><Upload size={16}/>Importar texto</button><button className="secondary" title="Exportar a Excel" onClick={()=>exportMovementsToCSV(filtered,'Brisa-Movimientos-'+month+'.csv')}><Download size={16}/>Exportar CSV</button></div><div className="list-summary"><span>{filtered.length} movimientos</span><span>Selecciona para editar o consultar la tarjeta</span></div>{movementList()}</section>}
 {view==='Presupuesto'&&<><section className="plan-intro"><div><span className="eyebrow">UN PLAN QUE SE ADAPTA A TI</span><h2>Disfruta hoy. Cuida tu mañana.</h2><p>Tu base mensual: <strong>{money(p.income)}</strong> de ingresos netos esperados.</p><button className="primary" onClick={()=>{setPlan(structuredClone(p));open('budget');}}><SlidersHorizontal size={17}/>Personalizar mi plan</button></div><div className="rule-cards">{[['50','Necesidades'],['30','Deseos'],['20','Ahorro']].map(([n,l])=><div key={n}><strong>{n}<small>%</small></strong><span>{l}</span></div>)}</div></section><div className="two-column"><section className="card"><div className="section-heading"><h2>Tu distribución mensual</h2><span className="mini-tag">Editable</span></div>{budgetList(true)}</section><section className="card advice"><Sparkles size={28}/><h2>Un punto de partida, no una regla rígida.</h2><p>El modelo 50/30/20 propone distribuir tus ingresos netos entre necesidades, deseos y ahorro. Ajusta estos porcentajes a tu realidad.</p><h3>Primero, lo esencial</h3><p>Incluye arriendo, alimentación básica, servicios, transporte y cuotas mínimas en tus necesidades.</p><h3>Disfrutar también tiene un lugar</h3><p>Planea viajes y consumo dentro de tus deseos. Un aporte para un viaje se cuenta una sola vez en su categoría.</p><h3>La meta se construye con aportes</h3><p>Registra el dinero que separas como «Aporte a meta». Reduce lo disponible del mes, pero no aparece como gasto de consumo.</p><a href="https://www.consumerfinance.gov/consumer-tools/educator-tools/youth-financial-education/teach/activities/analyzing-budgets/" target="_blank" rel="noreferrer">Referencia educativa: CFPB <ArrowUpRight size={14}/></a><p className="small muted">La distribución detallada de Brisa es un ejemplo editable, no una recomendación individual. La base del plan aplica a todos los meses.</p></section></div></>}
 {view==='Metas'&&<><div className="two-column">{[{category:'Ahorro',title:'Fondo de tranquilidad',icon:Sprout,goal:p.savingGoal,color:'#328875'},{category:'Viajes',title:'Tu próxima aventura',icon:Plane,goal:p.travelGoal,color:'#9a81bd'},{category:'Salud',title:'Tu salud y bienestar',icon:HeartPulse,goal:0,color:'#e4658f'},{category:'Educación',title:'Aprender y crecer',icon:GraduationCap,goal:0,color:'#528bdb'},{category:'Emergencias',title:'Fondo de emergencias',icon:ShieldCheck,goal:0,color:'#eb9945'}].map(g=>{const saved=all.filter(r=>r.kind==='saving'&&r.category===g.category).reduce((a,r)=>a+r.amount,0);return <section key={g.title} className="card goal-card"><span className="goal-icon" style={{background:g.color+'16',color:g.color}}><g.icon size={32}/></span><h2>{g.title}</h2><p className="muted">Aportes acumulados de todos los meses</p><strong className="goal-amount">{money(saved)}</strong>{g.goal>0&&<><div className="row-between muted"><span>Meta: {money(g.goal)}</span><strong>{Math.round(saved/g.goal*100)}%</strong></div><Progress value={saved/g.goal*100} color={g.color}/></>}{g.goal===0&&<p className="muted small">Dinero reservado de tus ingresos para esta meta.</p>}<button className="primary" onClick={()=>{setInboxId(null);setStartupPrompt(false);setDraft({...blank(),kind:'saving',category:g.category,description:g.title});setEdit(false);open('movement');}}><Plus size={17}/>Registrar aporte</button></section>;})}</div><div className="goal-note"><ShieldCheck size={20}/><p>Estos valores representan aportes registrados, no saldos bancarios verificados. Editar o eliminar un aporte actualiza la meta.</p><button className="text-button" onClick={()=>{setPlan(structuredClone(p));open('budget');}}>Editar objetivos</button></div></>}
  {view==='Conexiones'&&<AutomationSettings onInbox={()=>setView('Mensajes')} onProfile={()=>setView('Perfil')} onMovementCreated={async()=>{const r=await fetch('/api/finance');const d=await r.json();if(d.movements)setRows(d.movements);}}/>}
 <footer><span className="footer-brand">brisa.</span><span>Un poco de claridad, todos los días.</span><div className="legal-footer-links"><a href="/legal/privacidad" target="_blank" rel="noreferrer">Privacidad</a><span>·</span><a href="/legal/terminos" target="_blank" rel="noreferrer">Términos</a><span>·</span><a href="/legal/eliminacion-datos" target="_blank" rel="noreferrer">Eliminar datos</a></div><button onClick={()=>open('account')}><ShieldCheck size={14}/>Tu espacio privado</button></footer>
