 <div className="segmented">{(draft.kind==='saving'?[['saving','Aporte a meta']]:[['expense','Gasto'],['income','Ingreso']]).map(([k,l])=><button type="button" key={k} className={draft.kind===k?'selected':''} onClick={()=>{setError('');setDraft({...draft,kind:k as Movement['kind'],account:k==='income'?'Cuenta bancaria':'Tarjeta débito',category:k==='saving'?'Ahorro':visibleCategories(k as 'expense'|'income',p.categorySettings||defaultCategorySettings,[...all,...creditMovements])[0]});}}>{l}</button>)}</div>
