 {draft.kind==='income'&&<p className="small muted">Se registra con fecha {draft.date}. Suma a tus ingresos y a tu disponible del mes.</p>}
 {draft.kind==='saving'&&<><label>Elige tu meta<select className="goal-select" value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{goalOptions.map(c=><option key={c}>{c}</option>)}</select></label><div className="goal-funding"><CategoryIcon category={draft.category}/><div><strong>{draft.category}</strong><p>Origen: ingresos disponibles de {draft.date.slice(0,7)}</p></div></div><div className="funding-summary"><span>Disponible antes del aporte<strong>{money(goalAvailable)}</strong></span><span>Disponible después<strong className={goalAvailable-draft.amount<0?'negative':''}>{money(goalAvailable-draft.amount)}</strong></span></div>{draft.amount>goalAvailable&&<p className="info-note">El aporte supera el disponible registrado de este mes. Revisa si falta registrar algún ingreso.</p>}</>}
 {draft.kind==='expense'&&<><div className="category-shortcuts">{visibleCategories('expense',p.categorySettings||defaultCategorySettings,[...all,...creditMovements],draft.category,showAllCategories).slice(0,4).map(c=><button key={c} type="button" className={draft.category===c?'selected':''} onClick={()=>setDraft({...draft,category:c})}><CategoryIcon category={c}/><span>{c}</span></button>)}</div><div className="form-grid"><label>Categoría de gasto<select value={draft.category} onChange={e=>e.target.value==='__saving'?setDraft({...draft,kind:'saving',category:'Ahorro'}):setDraft({...draft,category:e.target.value})}>{visibleCategories('expense',p.categorySettings||defaultCategorySettings,[...all,...creditMovements],draft.category,showAllCategories).map(c=><option key={c} value={c}>{categoryEmoji[c]||''} {c}</option>)}{!edit&&!inboxId&&<option value="__saving">🐷 Ahorros · aportar a una meta</option>}</select></label><label>Fecha<input required type="date" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></label></div></>}
 {draft.kind==='income'&&<div className="form-grid"><label>Concepto de ingreso<select value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{visibleCategories('income',p.categorySettings||defaultCategorySettings,all,draft.category,showAllCategories).map(c=><option key={c} value={c}>{categoryEmoji[c]||''} {c}</option>)}</select></label><label>Fecha<input required type="date" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></label></div>}
 {draft.kind!=='saving'&&<div className="category-tools"><button type="button" className="text-button" onClick={()=>setShowAllCategories(v=>!v)}>{showAllCategories?'Usar mis preferencias':'Ver todas las categorías'}</button><button type="button" className="text-button" onClick={()=>{setModal(null);setView('Configuración');}}>Gestionar categorías</button></div>}
 {draft.kind!=='saving'&&<label>{draft.kind==='income'?'¿Dónde recibes el dinero?':'¿De dónde sale el dinero?'}<select required value={(draft.kind==='income'?incomeAccounts:paymentMethods).includes(draft.account)?draft.account:''} onChange={e=>setDraft({...draft,account:e.target.value})}><option value="" disabled>Selecciona un medio</option>{(draft.kind==='income'?incomeAccounts:paymentMethods).map(a=><option key={a} disabled={a==='Tarjeta de crédito'&&(edit||draft.id.startsWith('cc-')||draft.id.startsWith('fixed-')||!!inboxId)}>{a}</option>)}</select>{!(draft.kind==='income'?incomeAccounts:paymentMethods).includes(draft.account)&&<small>Registro anterior: {draft.account}. Elige el medio para guardar los cambios.</small>}</label>}
